CREATE TYPE "CefrLevel" AS ENUM ('A1', 'A2', 'B1', 'B2', 'C1');
CREATE TYPE "ProfileConfidence" AS ENUM ('LOW', 'MEDIUM', 'HIGH');
CREATE TYPE "AssessmentStatus" AS ENUM ('IN_PROGRESS', 'COMPLETED');
CREATE TYPE "AssessmentItemType" AS ENUM ('VOCABULARY', 'GRAMMAR', 'SENTENCE_ORDER', 'SCENARIO_RESPONSE', 'FREE_RESPONSE');
CREATE TYPE "ScenarioCategory" AS ENUM ('AIRPORT', 'HOTEL', 'RESTAURANT', 'SHOPPING', 'TRANSPORT', 'HELP');
CREATE TYPE "ScenarioSessionStatus" AS ENUM ('ACTIVE', 'COMPLETED');
CREATE TYPE "ScenarioOutcome" AS ENUM ('SUCCESS', 'PARTIAL', 'INCOMPLETE');
CREATE TYPE "ScenarioTurnRole" AS ENUM ('USER', 'ASSISTANT');
CREATE TYPE "VocabularyBookKind" AS ENUM ('SYSTEM', 'PERSONAL');
CREATE TYPE "LexicalItemType" AS ENUM ('WORD', 'PHRASE');
CREATE TYPE "LanguageSkillKind" AS ENUM ('GRAMMAR', 'EXPRESSION', 'PRAGMATICS');
CREATE TYPE "PracticeItemType" AS ENUM ('EXPRESSION_REVIEW', 'GRAMMAR_REVIEW', 'SCENARIO');

ALTER TABLE "VocabularyBook" ADD COLUMN "kind" "VocabularyBookKind" NOT NULL DEFAULT 'SYSTEM', ADD COLUMN "ownerId" TEXT;
ALTER TABLE "VocabularyWord" ADD COLUMN "itemType" "LexicalItemType" NOT NULL DEFAULT 'WORD', ADD COLUMN "cefrLevel" "CefrLevel", ADD COLUMN "spokenPriority" INTEGER;
ALTER TABLE "VocabularyBookWord" ADD COLUMN "contextMeaning" TEXT, ADD COLUMN "sourceScenario" TEXT, ADD COLUMN "sourceExample" TEXT;

CREATE TABLE "LanguageProfile" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "overallLevel" "CefrLevel" NOT NULL DEFAULT 'A1', "confidence" "ProfileConfidence" NOT NULL DEFAULT 'LOW', "vocabularyScore" INTEGER NOT NULL DEFAULT 0, "grammarScore" INTEGER NOT NULL DEFAULT 0, "sentenceBuildingScore" INTEGER NOT NULL DEFAULT 0, "taskCompletionScore" INTEGER NOT NULL DEFAULT 0, "naturalnessScore" INTEGER NOT NULL DEFAULT 0, "pronunciationScore" INTEGER, "listeningScore" INTEGER, "fluencyScore" INTEGER, "provisional" BOOLEAN NOT NULL DEFAULT true, "assessedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "LanguageProfile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AssessmentItem" ("id" TEXT NOT NULL, "version" INTEGER NOT NULL DEFAULT 1, "type" "AssessmentItemType" NOT NULL, "level" "CefrLevel" NOT NULL, "dimension" TEXT NOT NULL, "scenario" "ScenarioCategory", "prompt" TEXT NOT NULL, "options" JSONB, "correctAnswers" JSONB, "rubric" JSONB, "explanation" TEXT, "displayOrder" INTEGER NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, CONSTRAINT "AssessmentItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AssessmentAttempt" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "status" "AssessmentStatus" NOT NULL DEFAULT 'IN_PROGRESS', "version" INTEGER NOT NULL DEFAULT 1, "currentLevel" "CefrLevel" NOT NULL DEFAULT 'A2', "objectiveLevel" "CefrLevel", "expressionLevel" "CefrLevel", "confidence" "ProfileConfidence", "itemCount" INTEGER NOT NULL DEFAULT 0, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" TIMESTAMP(3), CONSTRAINT "AssessmentAttempt_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AssessmentResponse" ("id" TEXT NOT NULL, "attemptId" TEXT NOT NULL, "itemId" TEXT NOT NULL, "answer" JSONB NOT NULL, "isCorrect" BOOLEAN, "scores" JSONB, "evidence" JSONB, "provisional" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AssessmentResponse_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ScenarioTemplate" ("id" TEXT NOT NULL, "slug" TEXT NOT NULL, "category" "ScenarioCategory" NOT NULL, "title" TEXT NOT NULL, "description" TEXT NOT NULL, "userRole" TEXT NOT NULL, "aiRole" TEXT NOT NULL, "minTurns" INTEGER NOT NULL DEFAULT 6, "maxTurns" INTEGER NOT NULL DEFAULT 10, "objectives" JSONB NOT NULL, "starterPhrases" JSONB NOT NULL, "grammarFrames" JSONB NOT NULL, "difficultyVariants" JSONB NOT NULL, "version" INTEGER NOT NULL DEFAULT 1, "isActive" BOOLEAN NOT NULL DEFAULT true, CONSTRAINT "ScenarioTemplate_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ScenarioSession" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "templateId" TEXT NOT NULL, "level" "CefrLevel" NOT NULL, "status" "ScenarioSessionStatus" NOT NULL DEFAULT 'ACTIVE', "turnCount" INTEGER NOT NULL DEFAULT 0, "objectivesProgress" JSONB, "deferredFeedback" JSONB, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" TIMESTAMP(3), CONSTRAINT "ScenarioSession_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ScenarioTurn" ("id" TEXT NOT NULL, "sessionId" TEXT NOT NULL, "clientMessageId" TEXT, "role" "ScenarioTurnRole" NOT NULL, "content" TEXT NOT NULL, "evaluation" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ScenarioTurn_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ScenarioReport" ("id" TEXT NOT NULL, "sessionId" TEXT NOT NULL, "outcome" "ScenarioOutcome" NOT NULL, "dimensionScores" JSONB NOT NULL, "rewrites" JSONB NOT NULL, "grammarFrames" JSONB NOT NULL, "evidence" JSONB NOT NULL, "vocabulary" JSONB NOT NULL, "recommendation" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ScenarioReport_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LanguageSkill" ("id" TEXT NOT NULL, "code" TEXT NOT NULL, "kind" "LanguageSkillKind" NOT NULL, "title" TEXT NOT NULL, "level" "CefrLevel" NOT NULL, "description" TEXT NOT NULL, CONSTRAINT "LanguageSkill_pkey" PRIMARY KEY ("id"));
CREATE TABLE "UserSkillProgress" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "skillId" TEXT NOT NULL, "score" INTEGER NOT NULL DEFAULT 0, "evidenceCount" INTEGER NOT NULL DEFAULT 0, "consecutivePass" INTEGER NOT NULL DEFAULT 0, "lastPracticedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "UserSkillProgress_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DailyPracticePlan" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "planDate" DATE NOT NULL, "totalMinutes" INTEGER NOT NULL DEFAULT 15, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DailyPracticePlan_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DailyPracticePlanItem" ("id" TEXT NOT NULL, "planId" TEXT NOT NULL, "type" "PracticeItemType" NOT NULL, "position" INTEGER NOT NULL, "minutes" INTEGER NOT NULL, "title" TEXT NOT NULL, "reason" TEXT NOT NULL, "scenarioTemplateId" TEXT, "completedAt" TIMESTAMP(3), CONSTRAINT "DailyPracticePlanItem_pkey" PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "LanguageProfile_userId_key" ON "LanguageProfile"("userId");
CREATE INDEX "LanguageProfile_overallLevel_confidence_idx" ON "LanguageProfile"("overallLevel", "confidence");
CREATE INDEX "AssessmentItem_version_isActive_level_displayOrder_idx" ON "AssessmentItem"("version", "isActive", "level", "displayOrder");
CREATE INDEX "AssessmentAttempt_userId_status_startedAt_idx" ON "AssessmentAttempt"("userId", "status", "startedAt");
CREATE UNIQUE INDEX "AssessmentResponse_attemptId_itemId_key" ON "AssessmentResponse"("attemptId", "itemId");
CREATE INDEX "AssessmentResponse_attemptId_createdAt_idx" ON "AssessmentResponse"("attemptId", "createdAt");
CREATE UNIQUE INDEX "ScenarioTemplate_slug_key" ON "ScenarioTemplate"("slug");
CREATE INDEX "ScenarioTemplate_category_isActive_idx" ON "ScenarioTemplate"("category", "isActive");
CREATE INDEX "ScenarioSession_userId_status_startedAt_idx" ON "ScenarioSession"("userId", "status", "startedAt");
CREATE INDEX "ScenarioSession_templateId_completedAt_idx" ON "ScenarioSession"("templateId", "completedAt");
CREATE INDEX "ScenarioTurn_sessionId_createdAt_idx" ON "ScenarioTurn"("sessionId", "createdAt");
CREATE UNIQUE INDEX "ScenarioTurn_sessionId_clientMessageId_key" ON "ScenarioTurn"("sessionId", "clientMessageId");
CREATE UNIQUE INDEX "ScenarioReport_sessionId_key" ON "ScenarioReport"("sessionId");
CREATE UNIQUE INDEX "LanguageSkill_code_key" ON "LanguageSkill"("code");
CREATE UNIQUE INDEX "UserSkillProgress_userId_skillId_key" ON "UserSkillProgress"("userId", "skillId");
CREATE INDEX "UserSkillProgress_userId_score_lastPracticedAt_idx" ON "UserSkillProgress"("userId", "score", "lastPracticedAt");
CREATE UNIQUE INDEX "DailyPracticePlan_userId_planDate_key" ON "DailyPracticePlan"("userId", "planDate");
CREATE UNIQUE INDEX "DailyPracticePlanItem_planId_position_key" ON "DailyPracticePlanItem"("planId", "position");
CREATE INDEX "DailyPracticePlanItem_scenarioTemplateId_idx" ON "DailyPracticePlanItem"("scenarioTemplateId");
CREATE INDEX "VocabularyBook_ownerId_kind_idx" ON "VocabularyBook"("ownerId", "kind");

ALTER TABLE "VocabularyBook" ADD CONSTRAINT "VocabularyBook_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LanguageProfile" ADD CONSTRAINT "LanguageProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AssessmentAttempt" ADD CONSTRAINT "AssessmentAttempt_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AssessmentResponse" ADD CONSTRAINT "AssessmentResponse_attemptId_fkey" FOREIGN KEY ("attemptId") REFERENCES "AssessmentAttempt"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AssessmentResponse" ADD CONSTRAINT "AssessmentResponse_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "AssessmentItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ScenarioSession" ADD CONSTRAINT "ScenarioSession_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ScenarioSession" ADD CONSTRAINT "ScenarioSession_templateId_fkey" FOREIGN KEY ("templateId") REFERENCES "ScenarioTemplate"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ScenarioTurn" ADD CONSTRAINT "ScenarioTurn_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "ScenarioSession"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ScenarioReport" ADD CONSTRAINT "ScenarioReport_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "ScenarioSession"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "UserSkillProgress" ADD CONSTRAINT "UserSkillProgress_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "UserSkillProgress" ADD CONSTRAINT "UserSkillProgress_skillId_fkey" FOREIGN KEY ("skillId") REFERENCES "LanguageSkill"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "DailyPracticePlan" ADD CONSTRAINT "DailyPracticePlan_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "DailyPracticePlanItem" ADD CONSTRAINT "DailyPracticePlanItem_planId_fkey" FOREIGN KEY ("planId") REFERENCES "DailyPracticePlan"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "DailyPracticePlanItem" ADD CONSTRAINT "DailyPracticePlanItem_scenarioTemplateId_fkey" FOREIGN KEY ("scenarioTemplateId") REFERENCES "ScenarioTemplate"("id") ON DELETE SET NULL ON UPDATE CASCADE;
